function journeyRaceMarkup(r,division){
 const target=division>1?'승격권':'상위 6위',status={achieved:target+' 목표 달성',missed:target+' 목표 미달',secured:target+' 승점 확보',out:target+' 추격 종료',open:target+' 경쟁 진행 중'}[r.status],esc=escapeText;
 return '<section class="journey-race" aria-label="승점으로 보는 시즌 경쟁"><div class="journey-race-heading"><strong>'+status+'</strong><span>남은 리그 '+r.remaining+'경기</span></div><p>'+(r.status==='secured'?'다른 팀이 남은 경기를 모두 이겨도 목표 순위 밖으로 밀려나지 않습니다.':r.status==='out'?'남은 경기를 모두 이겨도 목표 순위에 도달할 수 없습니다.':r.remaining?'우리 팀이 얻을 수 있는 최대 승점은 '+r.maximum+'점입니다.':'최종 순위는 '+r.rank+'위입니다.')+'</p>'+(r.nextRival?'<p class="journey-race-opponent">다음 리그 상대 · '+esc(r.nextRival.name)+' · '+r.nextRival.rank+'위 / '+r.nextRival.points+'점</p>':'')+'<ol>'+r.contenders.map(c=>'<li><span>'+c.rank+'위 · '+esc(c.name)+'</span><strong>'+c.points+'점 <small>('+(c.gap>0?'우리보다 +'+c.gap:c.gap<0?'우리보다 '+c.gap:'승점 동률')+')</small></strong></li>').join('')+'</ol><small>확정 리그 기록 기준 · 승점 동률은 골득실로 순위가 바뀔 수 있습니다. 컵 결과는 제외합니다.</small></section>';
}
function renderManagerJourney(){
 if(view!=='club')return;
 const host=$('manager-journey');if(!host)return;
 const model=ManagerJourney.read(season),s=model.season,esc=escapeText;
 const challenge=model.challenge,challengeMarkup=challenge?'<section class="journey-campaign" aria-label="현재 시즌 목표"><div><span class="eyebrow">시즌 목표</span><strong>'+esc(challenge.title)+'</strong></div><p>'+esc(challenge.detail)+'</p><small>'+challenge.played+' / '+challenge.total+'경기 확정 · 현재 '+challenge.points+'점</small></section>':'';
 const chapter=typeof managerStoryChapter==='function'?managerStoryChapter(s):null,chapterMarkup=chapter?'<div class="manager-chapter"><small>가상 스토리 · 현재 시즌</small><h3>'+esc(chapter[0])+'</h3><p>'+esc(chapter[1])+'</p></div>':'';
 const ladder=model.ladder,tierNames=['Premier League','Championship','League One','League Two','National League'],ladderMarkup=ladder?'<section class="journey-ladder" aria-label="5부에서 1부까지 승격 경로"><div class="journey-ladder-heading"><strong>5부에서 1부까지</strong><span>1부까지 '+ladder.stepsRemaining+'계단</span></div><ol>'+ladder.tiers.map(t=>'<li class="'+(t.current?'current':t.visited?'passed':'ahead')+'"><span class="journey-tier-marker">'+(t.current?'●':t.visited?'✓':'○')+'</span><span><b>'+t.tier+'부</b><small>'+tierNames[t.tier-1]+'</small></span>'+(t.current?'<em>현재</em>':t.visited?'<em>경험</em>':'')+'</li>').join('')+'</ol><p>'+(ladder.nextTier?'이번 시즌 목표: '+esc(ladder.nextTier)+' 승격권 진입.':'최종 목표: 1부 잔류와 유럽 무대.')+'</p></section>':'';
 const arc=model.arc,arcMarkup=arc?'<section class="journey-arc" aria-live="polite"><div><span class="eyebrow">'+(arc.round===arc.total?'시즌의 마지막 무대':'이번 시즌의 발자취')+'</span><strong>'+esc(arc.headline)+'</strong></div><p>'+esc(arc.copy)+'</p><div class="journey-form" aria-label="최근 확정 경기 흐름">'+(arc.form.length?arc.form.map((result,i)=>'<span class="form-'+result.toLowerCase()+'" aria-label="최근 '+(arc.form.length-i)+'번째 경기 '+({W:'승리',D:'무승부',L:'패배'}[result])+'">'+result+'</span>').join(''):'<span class="form-empty">첫 경기 전</span>')+'</div></section>':'';
 const expanded=host.querySelector('details')?.open||false;
 host.innerHTML=`<section class="manager-journey-card" aria-labelledby="manager-journey-title"><div class="journey-heading"><div><span class="eyebrow">1부 귀환의 여정 · 감독의 이야기</span><h2 id="manager-journey-title">${ladder?'5부에서 시작하는 1부 귀환':'우승까지의 여정'}</h2></div><span class="journey-count">${model.completed} / ${model.total} 달성</span></div>${ladderMarkup}${challengeMarkup}<div class="journey-season"><span>${s.year}시즌 · ${s.division}부 · ${s.rank?s.rank+"위 · "+s.points+"점":"첫 경기 준비"}</span><span>${s.final?"리그 종료":"리그 "+s.remaining+"경기 남음"}</span></div><progress max="${s.total}" value="${s.played}" aria-label="확정된 리그 경기 ${s.played} / ${s.total}"></progress><details${expanded?" open":""}><summary>승격 경쟁 · 시즌 이야기 · 이정표</summary>${journeyRaceMarkup(model.race,s.division)}${arcMarkup}${chapterMarkup}<p class="journey-next"><strong>${model.next?'다음 도전 · '+esc(model.next.title):'모든 이정표 달성 · 이제 왕조를 이어가세요'}</strong><span>${model.next?esc(model.next.hint):'다음 시즌에도 새로운 선수와 함께 우승에 도전할 수 있습니다.'}</span></p><ol class="journey-milestones">${model.milestones.map(m=>`<li class="${m.achieved?'achieved':''}"><span class="journey-marker" aria-hidden="true">${m.achieved?'✓':'○'}</span><div><strong>${esc(m.title)}</strong><small>${m.achieved?'달성 · '+esc(m.evidence):esc(m.hint)}</small></div></li>`).join('')}</ol><p class="journey-carry">${esc(model.carry)}</p>${model.partial?'<p class="journey-carry">이전 저장에 없는 승리 기록은 추정하지 않습니다. 남아 있는 확정 기록부터 표시합니다.</p>':''}<p class="journey-carry">목표는 각각 달성할 수 있으며, 이정표 자체로 추가 자금이나 능력치를 지급하지 않습니다.</p></details><div class="journey-actions"><button type="button" id="journey-continue" class="secondary">${{season:'다음 시즌 준비',result:'경기 결과 확정하러 가기',match:'다음 경기 준비'}[model.action]}</button><button type="button" id="journey-journal" class="secondary">귀환 일지</button><button type="button" id="journey-competitions" class="text-button">대회 기록 보기 →</button></div></section>`;
 $('journey-continue').onclick=()=>{if(model.action==='season'){setMobileDashboardExpanded(true);$('next-season')?.scrollIntoView({block:'center',behavior:'instant'});$('next-season')?.focus({preventScroll:true});}else setView('match');};
 $('journey-competitions').onclick=()=>setView('cup');
 const journal=$('journey-journal');if(journal)journal.onclick=()=>openJourneyJournal(journal);
}
var journeyJournalModel=null,journeyJournalYear='all',journeyJournalReturn=null,journeyJournalBusy=false,journeyJournalToken=0;
function closeJourneyJournal(){journeyJournalToken++;journeyJournalBusy=false;$('journey-journal-dialog')?.close();journeyJournalReturn?.focus?.({preventScroll:true});}
function journeyJournalMarkup(m,year='all'){
 const entries=m.entries.filter(e=>year==='all'||e.year===Number(year)),esc=escapeText;
 return '<label class="journal-filter">시즌<select id="journey-journal-year"><option value="all"'+(year==='all'?' selected':'')+'>모든 시즌</option>'+m.years.map(y=>'<option value="'+y+'"'+(String(year)===String(y)?' selected':'')+'>'+y+'시즌</option>').join('')+'</select></label><p class="journal-note">통산 '+m.matches+'경기의 확정 기록에서 모은 귀환의 순간들.'+(m.partial?' 저장에 남아 있는 기록 이후의 첫 성과입니다.':'')+'</p>'+(entries.length?'<ol class="journal-timeline">'+entries.map(e=>'<li class="journal-memory journal-'+e.kind+'"><small>'+e.year+'시즌 · '+e.division+'부'+(e.recordId?' · '+({league:'리그 '+e.round+'R',cup:'국내컵',europe:'유럽 대회'}[e.competition]):' · 시즌 결산')+'</small><h3>'+esc(e.title)+'</h3>'+(e.playerIdentity&&typeof Portraits!=='undefined'?'<div class="journal-player">'+Portraits.html(F.identityProfile(e.playerIdentity))+'<span>'+esc(e.playerName)+'</span></div>':'')+(e.opponent?'<p>'+esc(S.club(S.own).short)+' <strong>'+e.score[0]+' : '+e.score[1]+'</strong> '+esc(e.opponent.name)+'</p>':'')+'<ul>'+e.badges.map(b=>'<li>'+esc(b)+'</li>').join('')+'</ul><button type="button" class="secondary" '+(e.recordId?'data-memory-game="'+esc(e.recordId)+'"':'data-memory-season="'+e.year+'"')+'>'+ (e.recordId?'그 경기 다시 보기':'시즌 결산 보기')+'</button></li>').join('')+'</ol>':'<div class="journal-empty"><strong>첫 페이지는 아직 비어 있습니다.</strong><p>첫 경기 결과를 확정하면 득점과 승리의 기억이 여기 남습니다. 진행 중인 경기는 기록하지 않습니다.</p></div>')+'<p class="journal-note">이 일지는 기록을 읽기만 합니다. 보상이나 선수 능력치를 추가하지 않으며, 실제 승격·트로피·출전 자료만 표시합니다.</p>';
}
function renderJourneyJournal(){
 const dialog=$('journey-journal-dialog');if(!dialog?.open||!journeyJournalModel)return;
 $('journey-journal-body').innerHTML=journeyJournalMarkup(journeyJournalModel,journeyJournalYear);
 $('journey-journal-year').onchange=e=>{journeyJournalYear=e.target.value;renderJourneyJournal();$('journey-journal-year').focus({preventScroll:true});};
 dialog.querySelectorAll('[data-memory-game]').forEach(b=>b.onclick=()=>{const id=b.dataset.memoryGame;closeJourneyJournal();openMatchArchive(id);});
 dialog.querySelectorAll('[data-memory-season]').forEach(b=>b.onclick=()=>{const year=Number(b.dataset.memorySeason);closeJourneyJournal();seasonReviewYear=year;setView('cup');$('season-review-title')?.scrollIntoView({block:'start',behavior:'instant'});$('season-review-title')?.focus({preventScroll:true});});
}
function openJourneyJournal(opener=document.activeElement){
 let dialog=$('journey-journal-dialog');if(journeyJournalBusy||dialog?.open)return;
 if(!dialog){dialog=document.createElement('dialog');dialog.id='journey-journal-dialog';dialog.setAttribute('aria-labelledby','journey-journal-title');dialog.innerHTML='<header class="journal-heading"><div><span class="eyebrow">귀환 일지</span><h2 id="journey-journal-title">나의 토투넘 귀환 일지</h2></div><button type="button" id="close-journey-journal" class="secondary" aria-label="귀환 일지 닫기">×</button></header><div id="journey-journal-body"></div>';document.body.append(dialog);$('close-journey-journal').onclick=closeJourneyJournal;dialog.addEventListener('cancel',e=>{e.preventDefault();closeJourneyJournal();});}
 pauseForPlanning();journeyJournalReturn=opener;journeyJournalModel=null;journeyJournalYear='all';journeyJournalBusy=true;const token=++journeyJournalToken;$('journey-journal-body').innerHTML='<p role="status" class="journal-note journal-loading"><progress aria-label="귀환 일지 준비 중"></progress>확정된 경기와 시즌 기록을 모으는 중…</p>';dialog.showModal();$('close-journey-journal').focus({preventScroll:true});
 requestAnimationFrame(()=>setTimeout(()=>{if(token!==journeyJournalToken||!dialog.open)return;try{journeyJournalModel=ManagerJourney.memories(season);journeyJournalBusy=false;renderJourneyJournal();}catch{journeyJournalBusy=false;$('journey-journal-body').innerHTML='<p role="alert" class="journal-note">귀환 일지를 읽지 못했습니다. 다시 시도해 주세요.</p><button type="button" id="journey-journal-retry" class="secondary">다시 시도</button>';$('journey-journal-retry').onclick=()=>{const target=journeyJournalReturn;closeJourneyJournal();openJourneyJournal(target);};}},0));
}
